function openEditProfileModal() {
if (!currentEditingWorkerData) return;
const w = currentEditingWorkerData;
const photoPreview = document.getElementById('edit-photo-preview');
editPhotoBase64 = w.photo_url || '';
if (photoPreview) photoPreview.src = w.photo_url || '/static/images/icons/mason.svg';
const nameInput = document.getElementById('edit-worker-name');
if (nameInput) nameInput.value = w.name || '';
const phoneInput = document.getElementById('edit-worker-phone');
const savedPhone = localStorage.getItem('km_worker_phone') || '';
if (phoneInput) phoneInput.value = savedPhone;
const birthYearSelect = document.getElementById('edit-worker-birth-year');
if (birthYearSelect) {
const currYear = new Date().getFullYear();
const maxYear = currYear - 18;
const minYear = currYear - 70;
let html = '';
for (let y = maxYear; y >= minYear; y--) {
html += `<option value="${y}">${y} (आयु ~${currYear - y} वर्ष)</option>`;
}
birthYearSelect.innerHTML = html;
birthYearSelect.value = w.birth_year || (currYear - 28);
}
const expInput = document.getElementById('edit-worker-exp');
if (expInput) expInput.value = w.experience_years || 1;
const rateInput = document.getElementById('edit-worker-rate');
if (rateInput) rateInput.value = w.daily_rate || 600;
editSelectedSkills = Array.isArray(w.skills) ? [...w.skills] : [];
renderEditSkillsGrid();
const stateSelect = document.getElementById('edit-worker-state');
if (stateSelect && typeof INDIA_STATES_DISTRICTS !== 'undefined') {
stateSelect.innerHTML = Object.keys(INDIA_STATES_DISTRICTS).map(s => {
return `<option value="${s}" ${s === w.state ? 'selected' : ''}>${s}</option>`;
}).join('');
handleEditStateChange(w.state || stateSelect.value, w.district);
}
const tehsilInput = document.getElementById('edit-worker-tehsil');
if (tehsilInput) tehsilInput.value = w.tehsil || '';
const villageInput = document.getElementById('edit-worker-village');
if (villageInput) villageInput.value = w.village || '';
const leaderCheckbox = document.getElementById('edit-worker-leader');
if (leaderCheckbox) {
leaderCheckbox.checked = !!w.is_team_leader;
toggleEditTeamSize(!!w.is_team_leader);
}
const teamSizeInput = document.getElementById('edit-worker-teamsize');
if (teamSizeInput) teamSizeInput.value = w.team_size || 1;
const bioInput = document.getElementById('edit-worker-bio');
if (bioInput) bioInput.value = w.bio_text || '';
const modal = document.getElementById('edit-profile-modal');
if (modal) {
modal.style.display = 'flex';
modal.classList.remove('hidden');
}
}
function closeEditProfileModal() {
const modal = document.getElementById('edit-profile-modal');
if (modal) {
modal.style.display = 'none';
modal.classList.add('hidden');
}
}
function renderEditSkillsGrid() {
const grid = document.getElementById('edit-skills-grid');
if (!grid || typeof STANDARD_TRADES === 'undefined') return;
grid.innerHTML = STANDARD_TRADES.filter(t => t.key !== 'all').map(t => {
const isSelected = editSelectedSkills.includes(t.key);
const bg = isSelected ? '#dcfce7' : '#ffffff';
const border = isSelected ? '#15803d' : '#cbd5e1';
const text = isSelected ? '#14532d' : '#334155';
return `
<div onclick="toggleEditSkill('${t.key}')" style="cursor: pointer; padding: 0.35rem 0.6rem; border-radius: 0.5rem; border: 1.5px solid ${border}; background-color: ${bg}; color: ${text}; font-size: 0.75rem; font-weight: 700; display: inline-flex; align-items: center; gap: 0.25rem;">
${isSelected ? '✓' : '+'} ${t.defaultName}
</div>
`;
}).join('');
}
function toggleEditSkill(skillKey) {
const idx = editSelectedSkills.indexOf(skillKey);
if (idx > -1) {
if (editSelectedSkills.length <= 1) {
alert('कम से कम एक हुनर (Skill) चुनना अनिवार्य है।');
return;
}
editSelectedSkills.splice(idx, 1);
} else {
if (editSelectedSkills.length >= 6) {
alert('आप अधिकतम 6 हुनर चुन सकते हैं।');
return;
}
editSelectedSkills.push(skillKey);
}
renderEditSkillsGrid();
}
function adjustEditRate(delta) {
const input = document.getElementById('edit-worker-rate');
if (!input) return;
let val = parseInt(input.value) || 600;
val = Math.max(350, Math.min(3000, val + delta));
input.value = val;
}
function adjustEditExp(delta) {
const input = document.getElementById('edit-worker-exp');
if (!input) return;
let val = parseInt(input.value) || 0;
val = Math.max(0, Math.min(50, val + delta));
input.value = val;
}
function handleEditStateChange(stateName, preselectedDistrict) {
const districtSelect = document.getElementById('edit-worker-district');
if (!districtSelect || typeof INDIA_STATES_DISTRICTS === 'undefined') return;
const districts = INDIA_STATES_DISTRICTS[stateName] || [];
districtSelect.innerHTML = districts.map(d => {
return `<option value="${d}">${d}</option>`;
}).join('');
if (preselectedDistrict && districts.includes(preselectedDistrict)) {
districtSelect.value = preselectedDistrict;
}
}
