async function handleEditPhotoSelect(input) {
if (!input.files || !input.files[0]) return;
const file = input.files[0];
const badge = document.getElementById('edit-photo-size-badge');
const preview = document.getElementById('edit-photo-preview');
const MAX_ALLOWED_BYTES = 50 * 1024; // 50 KB (51,200 bytes)
if (file.size > MAX_ALLOWED_BYTES) {
const originalKB = (file.size / 1024).toFixed(1);
const confirmCompress = confirm(
`⚠️ चुनी गई फोटो 50KB से बड़ी है (${originalKB} KB)!\n\n` +
`नियम: प्रोफाइल फोटो 50KB या उससे कम साइज की होना अनिवार्य है।\n\n` +
`क्या आप चाहते हैं कि इसे तुरंत 50KB के अंदर (<35KB) कंप्रेस किया जाए?`
);
if (!confirmCompress) {
input.value = '';
editPhotoBase64 = '';
if (badge) {
badge.className = 'text-xs font-bold text-red-600 block mt-1';
badge.innerText = `❌ फोटो अस्वीकृत: ${originalKB} KB (50KB से अधिक है)`;
}
return;
}
}
if (badge) {
badge.innerText = '⏳ कंप्रेस हो रही है (50KB के अंदर)...';
badge.className = 'text-xs font-bold text-amber-700 block mt-1 animate-pulse';
}
try {
if (typeof compressImage === 'function') {
editPhotoBase64 = await compressImage(file, 35 * 1024);
} else {
const reader = new FileReader();
editPhotoBase64 = await new Promise((res) => {
reader.onload = (e) => res(e.target.result);
reader.readAsDataURL(file);
});
}
const byteLen = typeof getBase64ByteLength === 'function' ? getBase64ByteLength(editPhotoBase64) : Math.floor(editPhotoBase64.length * 0.75);
const sizeKB = (byteLen / 1024).toFixed(1);
if (byteLen > MAX_ALLOWED_BYTES || editPhotoBase64.length > 70 * 1024) {
alert(`❌ फोटो का साइज 50KB से अधिक है (${sizeKB} KB)। कृपया 50KB से छोटी फोटो चुनें।`);
input.value = '';
editPhotoBase64 = '';
if (badge) {
badge.innerText = `❌ फोटो बड़ी है (${sizeKB} KB). 50KB से छोटी आवश्यक है।`;
badge.className = 'text-xs font-bold text-red-600 block mt-1';
}
return;
}
if (preview) preview.src = editPhotoBase64;
if (badge) {
badge.innerText = `📦 फोटो साइज: ${sizeKB} KB (50KB से कम - मान्य ✅)`;
badge.className = 'text-xs font-bold text-green-700 block mt-1';
}
} catch (err) {
console.error('Edit photo compression error:', err);
alert('फोटो 50KB के अंदर कंप्रेस नहीं हो सकी। कृपया 50KB से छोटी फोटो चुनें।');
input.value = '';
editPhotoBase64 = '';
if (badge) {
badge.innerText = `❌ 50KB से छोटी फोटो आवश्यक है`;
badge.className = 'text-xs font-bold text-red-600 block mt-1';
}
}
}
