function calculateEarnability() {
const dailyRate = parseInt(document.getElementById('calc-rate')?.value) || 700;
const daysPerMonth = parseInt(document.getElementById('calc-days')?.value) || 24;
const teamSize = parseInt(document.getElementById('calc-teamsize')?.value) || 1;
const rateDisplay = document.getElementById('calc-rate-display');
if (rateDisplay) rateDisplay.innerText = `₹${dailyRate}`;
const daysDisplay = document.getElementById('calc-days-display');
if (daysDisplay) daysDisplay.innerText = `${daysPerMonth} दिन`;
const teamDisplay = document.getElementById('calc-teamsize-display');
if (teamDisplay) teamDisplay.innerText = `${teamSize} व्यक्ति`;
const monthlySolo = dailyRate * daysPerMonth;
const monthlyTeam = monthlySolo * teamSize;
const urgentBonus = Math.round(monthlySolo * 0.20); // ~20% urgent demand premium
const soloResult = document.getElementById('calc-result-solo');
if (soloResult) soloResult.innerText = `₹${monthlySolo.toLocaleString('en-IN')}`;
const teamResult = document.getElementById('calc-result-team');
if (teamResult) teamResult.innerText = `₹${monthlyTeam.toLocaleString('en-IN')}`;
const urgentResult = document.getElementById('calc-result-urgent');
if (urgentResult) urgentResult.innerText = `+₹${urgentBonus.toLocaleString('en-IN')}`;
}
